function openDoor(e,n,i,r){let t=(new Date).toISOString().slice(0,10),d=new Audio("./assets/glocke.mp3"),s=new Audio("./assets/gesperrt.mp3");if(e.dataset.number||(e.dataset.number=e.innerHTML),!(t>=r))return e.innerHTML="Du darfst die Tür nicht vorher öffnen",e.style.fontSize="15px",e.style.backgroundColor="red",s.play(),void setTimeout(()=>{e.innerHTML=e.dataset.number,e.style.fontSize="16px",e.style.backgroundColor="rgb(245, 67, 54)"},4e3);e.innerHTML===e.dataset.number?(e.innerHTML=n,e.style.fontSize="15px",e.style.backgroundColor=i,d.play()):(e.innerHTML=e.dataset.number,e.style.fontSize="16px",e.style.backgroundColor="rgb(245, 67, 54)")}let spruche=["Nimm dir etwas Ruhe und du wirst mehr Energie haben. Finde A!","Lass die kleinen Momente des Glücks nicht an dir vorbeiziehen. Finde B!","Es ist Zeit, dich selbst mit Güte zu behandeln. Finde C!","Freundlichkeit ist das schönste Geschenk, das du geben kannst. Finde D!","Echte Freude kommt von innen. Finde E!","Ein Lächeln ist das beste Accessoire, das du tragen kannst. Finde F!","Jeder Tag ist eine neue Gelegenheit, etwas Schönes zu erleben. Finde G!","Erlaube dir, deine eigenen Erfolge zu feiern. Finde H!","Glück entsteht oft durch Aufmerksamkeit in kleinen Dingen. Finde I!","Eine positive Einstellung verändert alles. Finde J!","Jeder Tag bringt neue Möglichkeiten, dein Bestes zu geben. Finde K!","Der Winter erinnert uns daran, innezuhalten und nachzudenken. Finde L!","Veränderungen beginnen mit kleinen Schritten. Finde M!","Erlaube dir, einfach nur du selbst zu sein. Finde N!","Freude steckt in den einfachsten Dingen. Finde O!","Glaube an die Magie des Neuanfangs. Finde P!","Ein Schritt nach dem anderen führt ans Ziel. Finde Q!","Dankbarkeit verwandelt alltägliche Momente in Glück. Finde R!","Nimm dir Zeit, um die Schönheit des Augenblicks zu genießen. Finde S!","Vertrauen ist der Schlüssel zu innerem Frieden. Finde T!","Erinnerungen sind der wahre Schatz des Lebens. Finde U!","Jede kleine Geste der Freundlichkeit zählt. Finde V!","Verbringe Zeit mit den Menschen, die dir wichtig sind. Finde W!","Die besten Geschenke im Leben sind nicht materiell. Finde X!"],colors=["rgb(102, 138, 83)","rgb(128, 64, 0)","rgb(255, 192, 0)","rgb(255, 87, 51)","rgb(102, 204, 255)","rgb(153, 102, 255)","rgb(0, 153, 153)","rgb(204, 102, 102)","rgb(76, 153, 0)","rgb(255, 128, 128)","rgb(204, 153, 51)","rgb(51, 153, 255)","rgb(153, 204, 51)","rgb(255, 102, 178)","rgb(102, 102, 255)","rgb(255, 204, 153)","rgb(0, 128, 128)","rgb(255, 204, 204)","rgb(153, 255, 102)","rgb(255, 102, 102)","rgb(128, 128, 0)","rgb(102, 204, 153)","rgb(204, 102, 255)","rgb(255, 255, 153)"],dateset=["2026-12-01","2026-12-02","2026-12-03","2026-12-04","2026-12-05","2026-12-06","2026-12-07","2026-12-08","2026-12-09","2026-12-10","2026-12-11","2026-12-12","2026-12-13","2026-12-14","2026-12-15","2026-12-16","2026-12-17","2026-12-18","2026-12-19","2026-12-20","2026-12-21","2026-12-22","2026-12-23","2026-12-24"];for(let e=0;e<=23;e++){let n=e+1;document.body.innerHTML+=`<div class="door">${n}</div>`}let doors=document.querySelectorAll(".door");for(let e=0;e<doors.length;e++)doors[e].addEventListener("click",function(){openDoor(doors[e],spruche[e],colors[e],dateset[e])});